using System;
using System.Collections.Generic;
using UnityEngine;

// Local strategy simulation. No network calls, credentials or paid inference.
[Serializable] public sealed class CivilizationModel {
 [Serializable] public sealed class District { public int id,kind; public Vector3 normal; public float yaw,progress; public bool ready { get { return progress>=1; } } }
 [Serializable] public sealed class Colony { public string key,name;public int port;public Vector3 anchor;public float population=12;public int rockets;public float rocketWork;public bool fabricating;public List<District> districts=new List<District>(); }
 [Serializable] public sealed class Faction {public string name,species;public int port,relation,strength;}
 [Serializable] public sealed class War {public int id,enemy,source,target,tick;public float travel=24,combatTime,nativeClock;public bool resolved,won,raid,routed,flagship,scaled;public float[] friendly,hostile;public int playerKills;}
 [Serializable] public sealed class Goal {public string id,title,why;public int action;public float progress,utility;public int rewardOre,rewardScience;}
 public int version=1,nextId=1,blueprint,paint,launches,fleet=0,warsWon,dysonBuilt,dysonSystem;
 public float alloy=650,energy=340,science=80,influence=0,seconds,dysonWork,raidClock=0;
 public bool dysonWorking;public int ownedHulls=1;public string activeGoal="";
 public List<Colony> colonies=new List<Colony>();public List<Faction> factions=new List<Faction>();public List<War> wars=new List<War>();public List<string> completed=new List<string>();
 public static readonly string[] DistrictNames={"Pioneer command spire","Habitat district","Regolith foundry","Helios solar farm","Xenoscience observatory","Orbital launch complex","Orbital shipyard","Aegis defense battery"};
 public static readonly string[] DistrictDescriptions={"Establish a colony and its first 28 citizens.","Expand housing by 90. Streets, towers and living quarters.","Refine local regolith into 1.8 alloy per second.","Generate 4 energy per second for city infrastructure.","Produce 0.48 science per second while powered.","Fabricate and launch survey rockets through native physics.","Build warships and unlock larger player hulls.","Protect this planet. Strengthens friendly fleets during raids."};
 public static readonly int[] OreCost={100,70,85,65,115,140,180,150};
 public static readonly int[] EnergyCost={30,20,35,0,45,70,90,65};
 public static readonly int[] ScienceCost={0,0,0,0,20,35,60,40};
 public static readonly float[] BuildSeconds={6,7,8,6,10,12,15,12};
 public static readonly string[] HullNames={"KESTREL / Pathfinder","ATLAS / Deep-space hauler","LANCER / Battle corvette","SOVEREIGN / Star cruiser"};
 public static readonly string[] HullDescriptions={"Agile exploration frame. Swept wings, sensor mast and twin drives.","Cargo outriggers, reinforced bridge and ventral stores. +45 hull; 0.92x thrust.","Armored delta wings and four weapon hardpoints. +85 hull; +12% thrust; faster cannon and extra projectile.","Broad dreadnought silhouette, command tower and heavy engine banks. +150 hull; +20% thrust; heavy cannon and two extra projectiles."};
 public static readonly int[] HullOre={0,180,330,650};public static readonly int[] HullScience={0,45,90,180};
 public static readonly float[] HullThrust={1, .92f,1.12f,1.20f};public static readonly int[] HullHealth={0,45,85,150};
 public CivilizationModel(){factions.Add(new Faction{name="HELION CONCORD",species="Solar-born navigators",port=1,relation=35,strength=3});factions.Add(new Faction{name="VANTA SYNOD",species="Crystalline machine collective",port=2,relation=-25,strength=4});factions.Add(new Faction{name="MYCELIAL SWARM",species="Spacefaring alien hive",port=4,relation=-55,strength=5});}
 public int Count(int kind){int n=0;foreach(var c in colonies)foreach(var d in c.districts)if(d.kind==kind&&d.ready)n++;return n;}
 public int Count(Colony c,int kind){if(c==null)return 0;int n=0;foreach(var d in c.districts)if(d.kind==kind&&d.ready)n++;return n;}
 public Colony Find(string key){return colonies.Find(c=>c.key==key);}
 public int Level { get { if(dysonBuilt==12)return 5;if(dysonBuilt>=4)return 4;if(colonies.Count>=2&&launches>=1)return 3;if(launches>0&&Count(4)>0)return 2;return Count(0)>0?1:0; } }
 public string LevelName {get{return new[]{"PIONEER","SETTLEMENT","PLANETARY","INTERPLANETARY","STELLAR","TYPE II CIVILIZATION"}[Level];}}
 public float Population {get{float v=0;foreach(var c in colonies)v+=c.population;return v;}}
 public float PowerRate {get{return Count(3)*4+dysonBuilt*22-Count(0)*.15f-Count(1)*.35f-Count(2)*.65f-Count(4)*1.25f-Count(6)*1.2f-Count(7)*.7f;}}
 public bool CanPay(float a,float e,float s){return Finite(a)&&Finite(e)&&Finite(s)&&a>=0&&e>=0&&s>=0&&alloy+.001f>=a&&energy+.001f>=e&&science+.001f>=s;}
 public bool Pay(float a,float e,float s){if(!CanPay(a,e,s))return false;alloy=Mathf.Max(0,alloy-a);energy=Mathf.Max(0,energy-e);science=Mathf.Max(0,science-s);return true;}
 public bool CanBuild(int kind,Colony c,out string why){why="";if(kind<0||kind>=8){why="Unknown blueprint";return false;}if(c==null&&kind!=0){why="Found a command spire here first";return false;}if(c!=null&&kind==0){why="This planet already has a command spire";return false;}if(c!=null&&c.districts.Count>=24){why="Colony district budget reached (24)";return false;}if(kind>=5&&Count(4)==0){why="Complete a xenoscience observatory first";return false;}if(kind==6&&launches==0){why="Launch your first survey rocket";return false;}if(!CanPay(OreCost[kind],EnergyCost[kind],ScienceCost[kind])){why="Need "+OreCost[kind]+" alloy / "+EnergyCost[kind]+" energy / "+ScienceCost[kind]+" science";return false;}return true;}
 public District Build(int kind,string key,string name,int port,Vector3 normal,float yaw,out string why){if(port<0||port>=128||port%4==3){why="Choose a charted core world connected to the supply network";return null;}var c=Find(key);var owner=factions.Find(f=>f.port==port);if(c==null&&owner!=null&&owner.relation<70){why=owner.name+" territory / negotiate a treaty or win the orbital front";return null;}if(!CanBuild(kind,c,out why))return null;if(!Finite(normal.x)||!Finite(normal.y)||!Finite(normal.z)||!Finite(yaw)||normal.sqrMagnitude<.5f){why="Choose a valid planetary surface";return null;}if(!Pay(OreCost[kind],EnergyCost[kind],ScienceCost[kind]))return null;if(c==null){c=new Colony{key=key,name=name,port=port,anchor=normal.normalized};colonies.Add(c);}var d=new District{id=nextId++,kind=kind,normal=normal.normalized,yaw=yaw};c.districts.Add(d);return d;}
 public bool FabricateRocket(Colony c,out string why){why="";if(Count(c,5)==0){why="Build an orbital launch complex here";return false;}if(c.fabricating||c.rockets>=3){why="Rocket assembly busy or three rockets already ready";return false;}if(!Pay(90,60,12)){why="Need 90 alloy / 60 energy / 12 science";return false;}c.fabricating=true;c.rocketWork=0;return true;}
 public bool TakeRocket(Colony c){if(c==null||c.rockets<1)return false;c.rockets--;return true;}
 public bool BuyFleet(out string why){why="";if(Count(6)==0){why="Complete an orbital shipyard first";return false;}if(fleet>=24){why="Fleet command capacity is 24 ships";return false;}if(!Pay(95,40,15)){why="Need 95 alloy / 40 energy / 15 science";return false;}fleet++;return true;}
 public bool BuyHull(int type,out string why){why="";if(type<0||type>3){why="Unknown hull";return false;}if((ownedHulls&(1<<type))!=0)return true;if(type>=2&&Count(6)==0){why="Build an orbital shipyard to research military hulls";return false;}if(type==3&&Level<3){why="Reach interplanetary civilization first";return false;}if(!Pay(HullOre[type],0,HullScience[type])){why="Insufficient alloy or science";return false;}ownedHulls|=1<<type;return true;}
 public bool BeginDyson(int system,out string why){why="";if(system<0||system>=32){why="Choose one of the 32 core stars for your first megastructure";return false;}if(dysonBuilt>=12){why="Stellar collector shell complete";return false;}if(dysonWorking){why="A collector sector is already under construction";return false;}if(Level<3||Count(6)==0){why="Need an interplanetary civilization and an orbital shipyard";return false;}if(!Pay(260+dysonBuilt*20,160,75)){why="Need "+(260+dysonBuilt*20)+" alloy / 160 energy / 75 science";return false;}dysonSystem=system;dysonWorking=true;dysonWork=0;return true;}
 public bool Diplomacy(int enemy,out string why){why="";if(enemy<0||enemy>=factions.Count)return false;if(wars.Exists(w=>w.enemy==enemy&&!w.resolved)){why="Resolve the active war before opening a treaty";return false;}if(!Pay(75,35,10)){why="Need 75 alloy / 35 energy / 10 science for an envoy";return false;}factions[enemy].relation=Mathf.Min(100,factions[enemy].relation+35);influence+=12;return true;}
 public War Strike(int enemy,int source,bool raid,out string why){why="";if(enemy<0||enemy>=factions.Count)return null;if(wars.Exists(w=>w.enemy==enemy&&!w.resolved)){why="A front is already active with this civilization";return null;}if(!raid&&fleet<3){why="Assemble at least three warships";return null;}if(!raid&&colonies.Count==0){why="Establish a colony first";return null;}int ours=raid?Mathf.Min(6,Mathf.Max(1,fleet)):Mathf.Min(6,fleet);if(!raid)fleet-=ours;else fleet=Mathf.Max(0,fleet-ours);int theirs=Mathf.Clamp(factions[enemy].strength,2,6);var w=new War{id=nextId++,enemy=enemy,source=source,target=raid?source:factions[enemy].port,raid=raid,friendly=new float[ours+(raid&&Count(colonies.Find(c=>c.port==source),7)>0?1:0)],hostile=new float[theirs]};for(int i=0;i<w.friendly.Length;i++)w.friendly[i]=145+(raid?Count(colonies.Find(c=>c.port==source),7)*15:0);for(int i=0;i<theirs;i++)w.hostile[i]=110;factions[enemy].relation=-100;wars.Add(w);if(wars.Count>20)wars.RemoveAll(x=>x.resolved&&x.id<w.id-12);return w;}
 public static int Living(float[] hp){int n=0;foreach(float h in hp)if(h>0)n++;return n;}
 public void Resolve(War w){if(w.resolved)return;int ours=Living(w.friendly),theirs=Living(w.hostile);if(ours>0&&theirs>0)return;w.resolved=true;w.won=ours>0;if(w.won){warsWon++;fleet=Mathf.Min(24,fleet+ours);alloy+=160;science+=70;influence+=45;factions[w.enemy].strength=Mathf.Min(6,factions[w.enemy].strength+1);if(!w.raid&&!colonies.Exists(c=>c.port==w.target)){var c=new Colony{key=w.target==0?"HOME":"S"+(w.target/4)+"P"+(w.target%4),name="Liberated colony",port=w.target,anchor=new Vector3(.18f,.94f,-.29f).normalized,population=22};c.districts.Add(new District{id=nextId++,kind=0,progress=1,normal=c.anchor});colonies.Add(c);}}else{alloy*=.9f;energy*=.85f;} }
 public void StrategicCombat(War w,float dt){if(w.resolved)return;w.combatTime+=dt;while(w.combatTime>=1){w.combatTime-=1;w.tick++;HitNext(w.hostile,Living(w.friendly)*8,w.tick);HitNext(w.friendly,Living(w.hostile)*7,w.tick*7);Resolve(w);}}
 static void HitNext(float[] hp,float damage,int tick){var living=new List<int>();for(int i=0;i<hp.Length;i++)if(hp[i]>0)living.Add(i);if(living.Count>0){int i=living[Math.Abs(tick)%living.Count];hp[i]=Mathf.Max(0,hp[i]-damage);}}
 public void Tick(float dt,Func<War,bool> loaded){dt=Mathf.Clamp(dt,0,.1f);seconds+=dt;bool powered=energy>0||PowerRate>0;energy=Mathf.Clamp(energy+PowerRate*dt,0,1000000);alloy=Mathf.Clamp(alloy+Count(2)*(powered?1.8f:.18f)*dt,0,1000000);science=Mathf.Clamp(science+Count(4)*(powered?.48f:0)*dt,0,1000000);
  foreach(var c in colonies){float cap=28+Count(c,1)*90;c.population=Mathf.Min(cap,c.population+(powered?.42f:.04f)*dt);foreach(var d in c.districts)d.progress=Mathf.Min(1,d.progress+dt/BuildSeconds[d.kind]);if(c.fabricating){c.rocketWork+=dt/12;if(c.rocketWork>=1){c.fabricating=false;c.rockets++;}}}
  if(dysonWorking){dysonWork+=dt/24;if(dysonWork>=1){dysonBuilt++;dysonWork=0;dysonWorking=false;}}
  foreach(var w in wars){if(w.resolved)continue;if(w.travel>0)w.travel=Mathf.Max(0,w.travel-dt);else if(loaded==null||!loaded(w))StrategicCombat(w,dt);Resolve(w);}
  if(Level>=2&&colonies.Count>0){raidClock+=dt;if(raidClock>240){raidClock=0;int enemy=factions.FindIndex(f=>f.relation<0);if(enemy>=0){string reason;Strike(enemy,colonies[0].port,true,out reason);}}}
  CheckGoal();
 }
 public List<Goal> Recommendations(){var list=new List<Goal>();AddGoal(list,"found","A foothold among the stars","A command spire unlocks housing, production and local construction.",0,Count(0)>0?1:0,100,100,15);AddGoal(list,"power","Power the new frontier",PowerRate<0?"Your power balance is negative. Solar generation restores industry.":"A foundry and solar farm create a self-sustaining resource loop.",2,Mathf.Min(Count(2),1)*.5f+Mathf.Min(Count(3),1)*.5f,Count(0)>0?95:30,150,35);
  AddGoal(list,"science","Listen to an alien world","Research unlocks launch complexes, military hulls and megastructures.",4,Mathf.Min(1,Count(4)),Count(2)>0?85:20,170,70);AddGoal(list,"launch","Touch the edge of space","Launch an assembled survey rocket to 1 km above terrain.",5,Mathf.Min(1,launches),Count(4)>0?90:15,210,80);AddGoal(list,"expansion","Two worlds, one civilization","Land on another planet and found a command spire, or win a planetary war.",0,Mathf.Clamp01((colonies.Count-1f)),launches>0?85:10,250,100);AddGoal(list,"fleet","Peace through preparedness","A shipyard and three reserve warships protect your expanding worlds.",6,Mathf.Min(1,Count(6))*.4f+Mathf.Min(3,fleet)/3f*.6f,launches>0?80:8,200,90);AddGoal(list,"war","Win the orbital frontier","Support your fleet at a contested planet. Diplomacy can also prevent future raids.",7,Mathf.Min(1,warsWon),fleet>=3?78:5,250,100);AddGoal(list,"dyson","Catch the light of a star","Construct collector sectors around a star. Each sector supplies civilization-wide power.",8,dysonBuilt/12f,Level>=3?100:3,800,240);
  foreach(var g in list){if(g.id=="power"&&PowerRate<0)g.utility+=50;if(g.id=="war"&&wars.Exists(w=>!w.resolved&&w.raid))g.utility+=70;float cost=g.action<8?OreCost[Mathf.Clamp(g.action,0,7)]:260;float affordability=Mathf.Clamp01(alloy/Mathf.Max(1,cost));g.utility+=affordability*8-g.progress*5;}
  list.Sort((a,b)=>b.utility.CompareTo(a.utility));return list;
 }
 void AddGoal(List<Goal> list,string id,string title,string why,int action,float progress,float utility,int ore,int data){if(completed.Contains(id))return;list.Add(new Goal{id=id,title=title,why=why,action=action,progress=progress,utility=utility,rewardOre=ore,rewardScience=data});}
 public void CheckGoal(){if(string.IsNullOrEmpty(activeGoal))return;var goal=Recommendations().Find(g=>g.id==activeGoal);if(goal==null){activeGoal="";return;}if(goal.progress<.999f)return;if(!completed.Contains(goal.id)){completed.Add(goal.id);alloy+=goal.rewardOre;science+=goal.rewardScience;influence+=20;}activeGoal="";}
 static bool Finite(float n){return !float.IsNaN(n)&&!float.IsInfinity(n);}
 public bool Validate(){if(version!=1||colonies==null||factions==null||wars==null||completed==null||colonies.Count>128||factions.Count!=3||wars.Count>24)return false;foreach(float n in new[]{alloy,energy,science,influence,seconds,dysonWork,raidClock})if(!Finite(n)||n<0||n>2000000)return false;if(blueprint<0||blueprint>3||paint<0||paint>3||dysonBuilt<0||dysonBuilt>12||dysonSystem<0||dysonSystem>31||fleet<0||fleet>24||(ownedHulls&(1<<blueprint))==0)return false;var keys=new HashSet<string>();foreach(var c in colonies){if(c==null||c.key==null||!Finite(c.anchor.x)||!Finite(c.anchor.y)||!Finite(c.anchor.z)||c.anchor.sqrMagnitude<.5f||c.anchor.sqrMagnitude>1.5f||!keys.Add(c.key)||c.port<0||c.port>=128||c.port%4==3||c.districts==null||c.districts.Count>24||!Finite(c.population)||c.population<0||!Finite(c.rocketWork)||c.rockets<0||c.rockets>3)return false;foreach(var d in c.districts)if(d==null||d.kind<0||d.kind>7||!Finite(d.progress)||d.progress<0||d.progress>1||!Finite(d.normal.x)||!Finite(d.normal.y)||!Finite(d.normal.z)||d.normal.sqrMagnitude<.5f||d.normal.sqrMagnitude>1.5f)return false;}foreach(var faction in factions)if(faction==null||string.IsNullOrEmpty(faction.name)||faction.port<0||faction.port>=128||faction.port%4==3||faction.strength<1||faction.strength>6||faction.relation< -100||faction.relation>100)return false;foreach(var w in wars)if(w==null||w.enemy<0||w.enemy>=3||w.source<0||w.source>=128||w.target<0||w.target>=128||w.friendly==null||w.hostile==null||w.friendly.Length>8||w.hostile.Length>8||!Finite(w.travel)||w.travel<0||!Finite(w.nativeClock)||!Finite(w.combatTime))return false;foreach(var w in wars){foreach(float hp in w.friendly)if(!Finite(hp)||hp<0||hp>10000)return false;foreach(float hp in w.hostile)if(!Finite(hp)||hp<0||hp>10000)return false;}return true;}
}
